import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import ThoughtSpotShell from './components/ThoughtSpotShell';
import { TierProvider } from './config/TierContext';
import Sidebar, { SIDEBAR_WIDTH } from './components/NavHeader';
import TopHeader from './components/TopHeader';
import DashboardHome from './pages/DashboardHome';
import SearchPage from './pages/SearchPage';
import Portfolios from './pages/Portfolios';
import PlaceholderPage from './pages/PlaceholderPage';
import Analytics from './pages/Analytics';
import './App.css';

function App() {
  return (
    <TierProvider>
      <ThoughtSpotShell>
        <Router>
          <div className="App" style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#EEF1FA' }}>
            <Sidebar />
            <div
              style={{
                marginLeft: SIDEBAR_WIDTH,
                flex: 1,
                minHeight: '100vh',
                display: 'flex',
                flexDirection: 'column',
              }}
            >
              <TopHeader />
              <main style={{ flex: '1 1 auto', width: '100%', minWidth: 0, display: 'flex', flexDirection: 'column' }}>
                <Routes>
                  <Route path="/" element={<Navigate to="/dashboard" replace />} />
                  <Route path="/dashboard" element={<DashboardHome />} />
                  <Route path="/search" element={<SearchPage />} />
                  <Route path="/fleet" element={<Portfolios />} />
                  <Route
                    path="/car-sharing"
                    element={
                      <PlaceholderPage
                        title="Car Sharing"
                        description="Monitor and manage your car-sharing fleet, bookings, and utilisation rates."
                      />
                    }
                  />
                  <Route
                    path="/bike-sharing"
                    element={
                      <PlaceholderPage
                        title="Bike Sharing"
                        description="Track micro-mobility assets, docking stations, and ride activity."
                      />
                    }
                  />
                  <Route path="/analytics" element={<Analytics />} />
                  <Route
                    path="/operations"
                    element={
                      <PlaceholderPage
                        title="Operations"
                        description="Maintenance schedules, incident reports, and operational workflows."
                      />
                    }
                  />
                  <Route
                    path="/pricing"
                    element={<PlaceholderPage title="Pricing Intelligence" description="Dynamic pricing insights and revenue optimisation tools." />}
                  />
                  <Route path="/knowledge-hub" element={<PlaceholderPage title="Knowledge Hub" />} />
                </Routes>
              </main>
            </div>
          </div>
        </Router>
      </ThoughtSpotShell>
    </TierProvider>
  );
}

export default App;
